/*
 * Search box using the elasticlunr index generated by Zola
 * (`build_search_index = true` in config.toml).
 * Results use the just-the-docs markup so its styles apply.
 * The index is downloaded when the user starts typing.
 */
(function () {
  "use strict";

  var script = document.currentScript;
  var INDEX_URL = script.getAttribute("data-index");
  var LIB_URL = script.getAttribute("data-lib");
  var MAX_RESULTS = 10;
  var PREVIEW_CHARS = 140;

  var index = null;
  var loading = null;

  function loadScript(src) {
    return new Promise(function (resolve, reject) {
      var s = document.createElement("script");
      s.src = src;
      s.onload = resolve;
      s.onerror = reject;
      document.head.appendChild(s);
    });
  }

  function loadIndex() {
    if (!loading) {
      loading = loadScript(LIB_URL)
        .then(function () { return loadScript(INDEX_URL); })
        .then(function () { index = elasticlunr.Index.load(window.searchIndex); });
    }
    return loading;
  }

  function escapeHtml(s) {
    return s.replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }

  function escapeRegExp(s) {
    return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  }

  // Wraps the query terms found in `text` with a highlight span
  function highlight(text, terms) {
    var html = escapeHtml(text);
    if (terms.length === 0) return html;
    var rx = new RegExp("(" + terms.map(function (t) { return escapeRegExp(escapeHtml(t)); }).join("|") + ")", "gi");
    return html.replace(rx, '<span class="search-result-highlight">$1</span>');
  }

  // A fragment of `body` around the first query term found in it
  function preview(body, terms) {
    var lower = body.toLowerCase();
    var pos = -1;
    for (var i = 0; i < terms.length && pos < 0; i++) {
      pos = lower.indexOf(terms[i].toLowerCase());
    }
    if (pos < 0) pos = 0;
    var start = Math.max(0, pos - PREVIEW_CHARS / 2);
    var end = Math.min(body.length, start + PREVIEW_CHARS);
    var fragment = body.slice(start, end).replace(/\s+/g, " ").trim();
    return (start > 0 ? "… " : "") + highlight(fragment, terms) + (end < body.length ? " …" : "");
  }

  function relativeUrl(ref) {
    try {
      return new URL(ref, document.baseURI).pathname;
    } catch (e) {
      return ref;
    }
  }

  function render(results, query, container) {
    var terms = query.split(/\s+/).filter(function (t) { return t.length > 1; });
    if (results.length === 0) {
      container.innerHTML = '<p class="search-no-result">No results found</p>';
      return;
    }
    var html = '<ul class="search-results-list">';
    results.slice(0, MAX_RESULTS).forEach(function (r) {
      var doc = r.doc || index.documentStore.getDoc(r.ref) || {};
      var title = doc.title || r.ref;
      var url = relativeUrl(r.ref);
      html +=
        '<li class="search-results-list-item">' +
        '<a class="search-result" href="' + escapeHtml(url) + '">' +
        '<div class="search-result-title">' +
        '<div class="search-result-doc">' +
        '<svg viewBox="0 0 24 24" class="search-result-icon" aria-hidden="true"><use xlink:href="#svg-doc"></use></svg>' +
        '<div class="search-result-doc-title">' + highlight(title, terms) + '</div>' +
        '</div>' +
        '<span class="search-result-rel-url">' + escapeHtml(url) + '</span>' +
        '</div>' +
        (doc.body ? '<div class="search-result-previews"><div class="search-result-preview">' + preview(doc.body, terms) + '</div></div>' : '') +
        '</a></li>';
    });
    container.innerHTML = html + '</ul>';
  }

  function init() {
    var input = document.getElementById("search-input");
    var container = document.getElementById("search-results");
    var overlay = document.querySelector(".search-overlay");
    if (!input || !container) return;

    function show() { document.documentElement.classList.add("search-active"); }
    function hide() { document.documentElement.classList.remove("search-active"); }

    function update() {
      var query = input.value.trim();
      if (query === "") {
        hide();
        container.innerHTML = "";
        return;
      }
      loadIndex().then(function () {
        if (input.value.trim() !== query) return; // a newer query is pending
        var results = index.search(query, {
          bool: "AND",
          expand: true,
          fields: { title: { boost: 2 }, body: { boost: 1 } }
        });
        if (results.length === 0) {
          results = index.search(query, {
            bool: "OR",
            expand: true,
            fields: { title: { boost: 2 }, body: { boost: 1 } }
          });
        }
        render(results, query, container);
        show();
      }, function (err) {
        console.error("Could not load the search index", err);
      });
    }

    input.addEventListener("input", update);
    input.addEventListener("focus", function () {
      if (input.value.trim() !== "") update();
    });
    if (overlay) overlay.addEventListener("click", function () {
      hide();
      input.blur();
    });

    input.addEventListener("keydown", function (e) {
      var active = container.querySelector(".search-result.active");
      var all = Array.prototype.slice.call(container.querySelectorAll(".search-result"));
      var i = all.indexOf(active);
      switch (e.key) {
        case "Escape":
          e.preventDefault();
          input.value = "";
          update();
          input.blur();
          break;
        case "ArrowDown":
        case "ArrowUp":
          e.preventDefault();
          if (all.length === 0) return;
          if (active) active.classList.remove("active");
          i = e.key === "ArrowDown" ? Math.min(i + 1, all.length - 1) : Math.max(i - 1, 0);
          all[i].classList.add("active");
          all[i].scrollIntoView({ block: "nearest" });
          break;
        case "Enter":
          e.preventDefault();
          var target = active || all[0];
          if (target) window.location.href = target.href;
          break;
      }
    });

    // Like the former site: focus the search box unless jumping to an anchor
    if (!window.location.hash) input.focus({ preventScroll: true });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
